// PWBM function and type metadata for the native runtime.
//
// The metadata block is generated by src/vm/native/meta.py from the Python
// ProgramImage. It is embedded next to the PWB1 image and describes function
// parameter names, type specs and default code indices. It is a cache of
// shapes that already exist in the Python image, never a second source of
// truth.

#pragma once

#include <array>
#include <cstddef>
#include <cstdint>
#include <optional>
#include <string>
#include <vector>

namespace pwb {

struct Image;

enum class MetaTypeKind : std::uint8_t {
    Named = 0,
    Union = 1,
    Function = 2,
    Param = 3,
};

enum class MetaTypeFlag : std::uint8_t {
    Weak = 1 << 0,
    Const = 1 << 1,
    Reference = 1 << 2,
    ErrorUnion = 1 << 3,
    Rest = 1 << 4,
};

enum class MetaParameterFlag : std::uint8_t {
    Reference = 1 << 0,
    Weak = 1 << 1,
    Variadic = 1 << 2,
    HasDefault = 1 << 3,
};

enum class MetaFunctionFlag : std::uint32_t {
    Async = 1 << 0,
    Variadic = 1 << 1,
    Lambda = 1 << 2,
    MutableCapture = 1 << 3,
    InstanceMethod = 1 << 4,
    Static = 1 << 5,
    SignatureOnly = 1 << 6,
    TraitMember = 1 << 7,
};

struct MetaTypeSpec {
    MetaTypeKind kind = MetaTypeKind::Named;
    std::string name;
    std::string nominal;
    std::uint8_t flags = 0;
    std::vector<std::uint32_t> args;
    std::vector<std::uint32_t> params;
    std::uint32_t returns = 0xFFFFFFFFu;
};

struct MetaParameter {
    std::string name;
    std::uint32_t type_index = 0;
    std::uint8_t flags = 0;
    std::int32_t default_index = -1;
};

struct FunctionMetadata {
    std::string name;
    std::uint32_t code_index = 0;
    std::uint32_t min_argc = 0;
    std::uint32_t flags = 0;
    std::int32_t variadic_index = -1;
    std::vector<MetaParameter> parameters;
    std::vector<std::string> type_parameters;
    std::string function_type;
    std::optional<std::string> lambda_name;
    std::vector<std::int32_t> defaults;
};

struct Meta {
    std::uint16_t version = 0;
    std::uint16_t flags = 0;
    std::array<std::uint8_t, 32> image_hash{};
    std::vector<MetaTypeSpec> types;
    std::vector<FunctionMetadata> functions;
};

Meta parse_meta(const std::uint8_t* data, std::size_t size);
void validate_meta(const Meta& meta, const Image& image);
std::string format_meta_summary(const Meta& meta);

inline bool meta_flag(MetaTypeSpec spec, MetaTypeFlag flag) {
    return (spec.flags & static_cast<std::uint8_t>(flag)) != 0;
}

inline bool meta_flag(MetaParameter parameter, MetaParameterFlag flag) {
    return (parameter.flags & static_cast<std::uint8_t>(flag)) != 0;
}

inline bool meta_flag(FunctionMetadata function, MetaFunctionFlag flag) {
    return (function.flags & static_cast<std::uint32_t>(flag)) != 0;
}

} // namespace pwb
